// 1 · Intake, Config & Guard  —  v3  (Code node, typeVersion 2)
// =============================================================================
// CHANGES FROM v2 (each marked [v3-N] inline):
//   [v3-1] THREE-WAY ROUTING. _route is now 'score' | 'review' | 'auto_reject',
//          produced by one decideRoute() function instead of a ternary. Intake
//          can now itself auto-reject on hard policy (not on a judgement call).
//   [v3-2] workflowVersion is READ FROM CONFIG, not hard-coded '4.0.0-agent'.
//   [v3-3] sourceRecipientEmail captured into _meta.recipientEmail (§C-2).
//   [v3-4] O-4 ROOT FIX: _resume.binaryProperty is no longer blanked when the
//          item routes to review. v2 blanked it while 'Has Resume PDF to
//          Archive?' still gated on _resume.isPdf (which stays true), so the
//          Drive node was handed an empty inputDataFieldName and threw. The
//          extractability decision now lives in its own field.
//   [v3-5] Auto-reject config surfaced onto cfg.autoReject for node 5/6.
//   [v3-6] Circuit-breaker counter for auto-rejections per company per hour.
// =============================================================================

// ---- shared helpers (inlined; n8n Code nodes do not share scope) -------------
function safeRequire(name) { try { return require(name); } catch (e) { return null; } }
function sha256Hex(str) {
  const c = safeRequire('crypto');
  if (c && typeof c.createHash === 'function') {
    try { return c.createHash('sha256').update(String(str), 'utf8').digest('hex'); } catch (e) { /* fall through */ }
  }
  const mix = (s, seed) => {
    let h = seed >>> 0;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return ('00000000' + h.toString(16)).slice(-8);
  };
  const s = String(str);
  const r = s.split('').reverse().join('');
  return mix(s, 0x811c9dc5) + mix(r, 0x01000193) + mix(s + r, 0x9e3779b9) + mix(String(s.length) + s, 0x85ebca6b);
}
function clampStr(s, n) {
  const v = (s === null || s === undefined) ? '' : String(s);
  return v.length <= n ? v : v.slice(0, n - 14) + '\n[TRUNCATED]';
}
function asArray(v) { return Array.isArray(v) ? v : (v === null || v === undefined || v === '' ? [] : [v]); }
function nowIso() { return new Date().toISOString(); }

// -----------------------------------------------------------------------------
// 1. Configuration — read from the ⚙️ Workflow Config node.
