const pickCfg = (k, d) => (cfgInput[k] === undefined || cfgInput[k] === null || cfgInput[k] === '' ? d : cfgInput[k]);

const rawMode = String(pickCfg('runMode', 'probe')).toLowerCase();
const runMode = ['live', 'dry_run', 'probe'].includes(rawMode) ? rawMode : 'probe'; // [v3] unknown => SAFEST, not 'live'
const liveArmed = pickCfg('liveArmed', false) === true;
const isProbe = runMode === 'probe';

