  chat: {
    hiringDefault: String(pickCfg('chatSpaceHiringDefault', 'spaces/AAQABbRdKHM')),
    allNotifications: String(pickCfg('chatSpaceAllNotifications', 'spaces/AAQA5Do_zwM')),
    audit: String(pickCfg('chatSpaceAudit', 'spaces/AAQA5Do_zwM')),
  },

  hubspot: {
    enabled: pickCfg('hubspotEnabled', false) === true,
    dryRun: pickCfg('hubspotDryRun', true) !== false,
    baseUrl: 'https://api.hubapi.com',
    upsertPath: '/crm/v3/objects/contacts/batch/upsert',
    timeoutMs: Number(pickCfg('hubspotTimeoutMs', 30000)),
  },

  companies: {
    green_attic: { companyKey: 'green_attic', company: 'Acme Home Services', scorecardTab: 'scorecards_green_attic', hubspotPortalId: '', hiringOwner: 'Alejandra Campos' },
    bb8_freight: { companyKey: 'bb8_freight', company: 'BB8 Freight', scorecardTab: 'scorecards_bb8_freight', hubspotPortalId: '', hiringOwner: 'Alejandra Campos' },
  },
};

const configErrors = [];
const configWarnings = asArray(cfgInput._cfgSelfCheck).slice();
if (cfg.thresholds.strongFit <= cfg.thresholds.goodFit) configErrors.push('strongFit must exceed goodFit');
if (cfg.thresholds.goodFit <= cfg.thresholds.needsReview) configErrors.push('goodFit must exceed needsReview');
if (!cfg.sheets.opsSpreadsheetId) (isProbe ? configWarnings : configErrors).push('opsSpreadsheetId is not configured');
// [v3] Loud, early guard against the single most expensive mistake available:
// running v3 while pointed at v2's live tabs.
if (cfg.environment !== 'prod' && !/_v3$/.test(cfg.sheets.auditTab)) configErrors.push('ISOLATION_BREACH: non-prod v3 pointed at ' + cfg.sheets.auditTab);
if (cfg.environment !== 'prod' && !/_v3$/.test(cfg.d1.table)) configErrors.push('ISOLATION_BREACH: non-prod v3 pointed at D1 table ' + cfg.d1.table);
if (cfg.autoReject.enabled && cfg.runMode === 'probe') configWarnings.push('auto_reject_enabled_but_probe_mode_no_crm_write');

// -----------------------------------------------------------------------------
// 2. Field helpers
// -----------------------------------------------------------------------------
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const pick = (json, aliases) => {
  const keys = Object.keys(json || {});
  for (const alias of aliases) {
    const hit = keys.find((k) => norm(k) === norm(alias));
    if (hit !== undefined) {
      const v = json[hit];
      if (v !== null && v !== undefined && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};
const clean = (v, max) => clampStr(String(v === null || v === undefined ? '' : v).replace(/[\x00-\x1f\x7f]/g, ' ').replace(/\s+/g, ' '), max).trim();
const normEmail = (v) => { const e = String(v || '').trim().toLowerCase(); return /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(e) && e.length <= 254 ? e : ''; };
const normPhone = (v) => { const d = String(v || '').replace(/\D+/g, ''); if (d.length < 10 || d.length > 15) return ''; return d.length === 10 ? '+1' + d : '+' + d; };

const COMPANY_MAP = {
  Acme Home Services: 'green_attic', Acme Home Servicesinsulation: 'green_attic',
  bb8freight: 'bb8_freight', bb8: 'bb8_freight', bb8freightllc: 'bb8_freight'
};
const MAGIC = { pdf: ['JVBER'], zip: ['UEsDB', 'UEsFB', 'UEsHB'], rtf: ['e1xydG'] };
const startsWithAny = (b64, list) => list.some((p) => b64.slice(0, p.length + 2).indexOf(p) === 0);

const store = $getWorkflowStaticData('global');
if (!store.formRate || typeof store.formRate !== 'object') store.formRate = {};
if (!store.seen || typeof store.seen !== 'object') store.seen = {};
if (!store.autoRejectRate || typeof store.autoRejectRate !== 'object') store.autoRejectRate = {};  // [v3-6]
const nowMs = Date.now();
const hourBucket = Math.floor(nowMs / 3600000);

// -----------------------------------------------------------------------------
// 3. Per-item processing
// -----------------------------------------------------------------------------
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const src = item.json || {};
  const binary = item.binary || {};
  const flags = [];
  const warnings = [];
  const reasons = [];

  // ---- 3a. company + raw intake fields ---------------------------------------
  const companyRaw = pick(src, ['Company', 'Company Applied To', 'Employer', 'Brand']);
  const companyKey = COMPANY_MAP[norm(companyRaw)] || '';
  const company = cfg.companies[companyKey] || null;
  const ctx = company || { companyKey: companyKey || 'unknown', company: 'UNKNOWN', scorecardTab: '', hubspotPortalId: '', hiringOwner: '' };

  const pastedText = pick(src, ['Resume Text', 'Resume Text (paste if no file)', 'Paste Resume', 'Resume', 'Resume Contents']);
  const accessCode = pick(src, ['Access Code', 'Access Code (if required)', 'Passcode', 'Code']);

  // [v3-3] WHICH RECRUITER MAILBOX RECEIVED THIS.
  // 'Parse Indeed Application Email' has always computed recipient_email from
  // Delivered-To / To, but every 'Map … → Intake Fields' node dropped it on the
  // floor, so it never reached _meta, HubSpot, or the Chat card. Read it from
  // every alias the three intake paths can produce, plus the raw parser field.
  const sourceRecipientEmail = normEmail(pick(src, [
    'sourceRecipientEmail', 'source_recipient_email', 'recipientEmail',
    'recipient_email', 'Delivered To', 'deliveredTo', 'Source Recipient'
  ]));

  const form = {
    companyRaw,
    roleApplied: pick(src, ['Role Applied For', 'Role', 'Position', 'Job Title', 'Job']),
    candidateName: pick(src, ['Candidate Name', 'Applicant Name', 'Name', 'Full Name']),
    candidateEmail: pick(src, ['Candidate Email', 'Email', 'Applicant Email', 'Email Address']),
    candidatePhone: pick(src, ['Candidate Phone', 'Phone', 'Phone Number', 'Mobile']),
    location: pick(src, ['Location', 'City', 'City And State']),
    indeedLink: pick(src, ['Indeed Application URL', 'Indeed Link', 'Application URL', 'Indeed URL']),
    submittedBy: pick(src, ['Submitted By', 'Your Name', 'Recruiter', 'Submitter']),
    notes: clampStr(pick(src, ['Notes', 'Note', 'Comments', 'Context']), 1500),
    pastedText: clampStr(pastedText, 200000),
    pastedTextChars: pastedText.length,
    submittedAt: String(src.submittedAt || src.submitted_at || nowIso())
  };

  // ---- 3b. trust gate ---------------------------------------------------------
  if (configErrors.length) reasons.push('config_error:' + configErrors.join('|'));
  if (!company) reasons.push('company_not_selected_or_unrecognised:' + companyRaw.slice(0, 40));

  const rateKey = (src.source || 'form') + ':' + (ctx.companyKey || 'unknown') + ':' + hourBucket;
  store.formRate[rateKey] = (store.formRate[rateKey] || 0) + 1;
  if (store.formRate[rateKey] > cfg.form.maxPerHour) reasons.push('rate_limit_exceeded:' + store.formRate[rateKey] + '/' + cfg.form.maxPerHour);
  for (const k of Object.keys(store.formRate)) {
    const hr = Number(String(k).split(':').pop());
    if (!Number.isFinite(hr) || hr < hourBucket - 3) delete store.formRate[k];
  }

  const hasFile = Object.keys(binary).length > 0;
  const hasText = form.pastedTextChars >= 1;
  if (!hasFile && !hasText) reasons.push('no_resume_file_and_no_pasted_text');
  if (hasFile && hasText) warnings.push('both_file_and_text_supplied_both_will_be_used');

  const trusted = reasons.length === 0;
  if (!trusted) flags.push('trust_rejected:' + reasons.length);
  warnings.forEach((w) => flags.push(w));

  // ---- 3c. idempotency ---------------------------------------------------------
  const dedupeKey = (ctx.companyKey || 'unknown') + ':' + (src.source || 'form') + ':' + sha256Hex([
    form.roleApplied, form.candidateName, form.candidateEmail,
    String(form.pastedText).slice(0, 4000),
    Object.keys(binary).map((k) => (binary[k].fileName || '') + ':' + (binary[k].fileSize || '')).join('|')
  ].join('~'));
  const ttlMs = cfg.limits.dedupeTtlHours * 3600000;
  const prior = store.seen[dedupeKey];
  const isRepeat = !!prior && (nowMs - prior) < ttlMs;
  const isDuplicate = isRepeat && cfg.form.dedupeEnabled;
  store.seen[dedupeKey] = nowMs;
  if (isRepeat && !isDuplicate) flags.push('repeat_submission_allowed_dedupe_disabled');
  if (isDuplicate) flags.push('duplicate_submission_suppressed');

  for (const k of Object.keys(store.seen)) { if (nowMs - store.seen[k] > ttlMs) delete store.seen[k]; }
  const seenKeys = Object.keys(store.seen);
  if (seenKeys.length > cfg.limits.dedupeMaxKeys) {
    seenKeys.sort((a, b) => store.seen[a] - store.seen[b]).slice(0, seenKeys.length - cfg.limits.dedupeMaxKeys).forEach((k) => delete store.seen[k]);
  }

  // ---- 3d. candidate normalisation ---------------------------------------------
  const roleApplied = clean(form.roleApplied, 120);
  const candidateName = clean(form.candidateName, 80).replace(/[<>"'`\\]/g, '');
  const email = normEmail(form.candidateEmail);
  const phone = normPhone(form.candidatePhone);
  if (form.candidateEmail && !email) flags.push('form_email_invalid_discarded');
  if (form.candidatePhone && !phone) flags.push('form_phone_invalid_discarded');
  if (!roleApplied) flags.push('role_not_identified');
  if (!candidateName) flags.push('form_no_candidate_name');
  if (!email) flags.push('form_no_candidate_email');
  if (!sourceRecipientEmail && String(src.source || '') === 'indeed_gmail') flags.push('source_recipient_email_missing');

  // Hand-rolled URL validation: this sandbox has no URL global.
  let indeedLink = '';
  const rawIndeedLink = String(form.indeedLink || '').trim();
  if (rawIndeedLink) {
    const m = /^https:\/\/([^\/?#\s]+)([^\s]*)$/i.exec(rawIndeedLink);
    if (m) {
      let hostPart = m[1];
      const atIdx = hostPart.lastIndexOf('@');
      if (atIdx !== -1) hostPart = hostPart.slice(atIdx + 1);
      const host = hostPart.split(':')[0].toLowerCase();
      if (cfg.security.allowedLinkHosts.some((h) => host === h || host.endsWith('.' + h))) {
        indeedLink = ('https://' + m[1] + m[2]).slice(0, 900);
      } else {
        flags.push('form_link_rejected_not_allowlisted:' + host.slice(0, 40));
      }
    }
  }

  // ---- 3e. attachment selection (security gate) --------------------------------
  const rejected = [];
  const accepted = [];
  for (const key of Object.keys(binary)) {
    const b = binary[key] || {};
    const fileName = String(b.fileName || '').trim();
    const mime = String(b.mimeType || '').toLowerCase().split(';')[0].trim();
    const ext = String(b.fileExtension || (fileName.includes('.') ? fileName.split('.').pop() : '')).toLowerCase().replace(/[^a-z0-9]/g, '');
    const declaredSize = Number(b.fileSize && String(b.fileSize).match(/^\d+$/) ? b.fileSize : NaN);
    const b64 = (typeof b.data === 'string' && !b.id) ? b.data : '';
    const byteSize = Number.isFinite(declaredSize) ? declaredSize : (b64 ? Math.floor(b64.length * 3 / 4) : NaN);

    const why = [];
    if (/[\x00-\x1f]/.test(fileName) || /(\.\.|[\/\\])/.test(fileName)) why.push('unsafe_filename');
    if (!cfg.security.allowedAttachmentExt.includes(ext)) why.push('extension_not_allowed:' + (ext || 'none'));
    if (mime && !cfg.security.allowedAttachmentMime.includes(mime)) why.push('mime_not_allowed:' + mime);
    if (Number.isFinite(byteSize) && byteSize > cfg.limits.maxAttachmentBytes) why.push('too_large_bytes:' + byteSize);
    if (Number.isFinite(byteSize) && byteSize < 64) why.push('too_small_bytes:' + byteSize);
    if (/\.(exe|js|jse|vbs|scr|bat|cmd|com|ps1|jar|msi|dll|sh|html?|svg|zip|rar|7z|iso|lnk)$/i.test(fileName)) why.push('dangerous_extension');

    let magicChecked = false;
    if (b64) {
      magicChecked = true;
      if (ext === 'pdf' && !startsWithAny(b64, MAGIC.pdf)) why.push('magic_mismatch_not_pdf');
      if ((ext === 'docx' || ext === 'odt') && !startsWithAny(b64, MAGIC.zip)) why.push('magic_mismatch_not_zip');
      if (ext === 'rtf' && !startsWithAny(b64, MAGIC.rtf)) why.push('magic_mismatch_not_rtf');
      if (startsWithAny(b64, ['PCFET0NUWVBF', 'PGh0bWw', 'PD9waHA', 'IyEv'])) why.push('magic_looks_like_html_or_script');
    }

    const rec = { binaryProperty: key, fileName: fileName.slice(0, 200), mimeType: mime, ext, byteSize: Number.isFinite(byteSize) ? byteSize : null, magicChecked };
    if (why.length) rejected.push({ ...rec, reasons: why }); else accepted.push(rec);
  }

  const score = (a) => (a.ext === 'pdf' ? 100 : a.ext === 'docx' ? 80 : a.ext === 'doc' ? 70 : a.ext === 'odt' ? 60 : a.ext === 'rtf' ? 50 : 30)
    + (/(resume|cv|curriculum)/i.test(a.fileName) ? 25 : 0)
    - (/(cover|letter|reference|transcript|portfolio)/i.test(a.fileName) ? 15 : 0);
  accepted.sort((a, b) => score(b) - score(a));
  const chosen = accepted[0] || null;

  if (rejected.length) flags.push('attachment_rejected:' + rejected.length);
  if (rejected.some((r) => r.reasons.some((x) => x.startsWith('magic_') || x === 'dangerous_extension'))) flags.push('attachment_security_reject');
  if (!accepted.length && Object.keys(binary).length) flags.push('no_usable_attachment');
  if (!Object.keys(binary).length) flags.push('form_no_file_upload');
  if (chosen && !chosen.magicChecked) flags.push('magic_check_skipped_filesystem_binary_mode');

  // ---- 3f. ROUTING — three-way [v3-1] ------------------------------------------
  // Auto-rejection at INTAKE is deliberately narrow. Only hard, mechanical policy
  // belongs here; anything requiring judgement about the candidate waits for the
  // scorecard gates in node 6, where the evidence actually exists.
  //
  // NON-NEGOTIABLE: a technical failure NEVER routes to auto_reject. Unparseable
  // PDFs, missing scorecards, API timeouts and config errors all degrade to
  // 'review' so a human sees them. Auto-rejection is a CONFIGURED BUSINESS
  // DECISION, never an error path.
  const intakeAutoReject = (() => {
    if (!cfg.autoReject.enabled) return null;
    // A security-rejected attachment is a policy decision, not a candidate
    // judgement — but it is also evidence we could not read the document, so it
    // goes to review, not auto_reject. Deliberately returns null.
    return null;
  })();

  const decideRoute = () => {
    if (intakeAutoReject) return 'auto_reject';
    if (!trusted || isDuplicate) return 'review';
    return 'score';
  };
  const route = decideRoute();

  // [v3-4] O-4 ROOT FIX.
  // v2: binaryProperty = (route === 'score' && chosen && chosen.ext === 'pdf') ? … : ''
  //     but 'Has Resume PDF to Archive?' gates on _resume.isPdf, which stays TRUE
  //     for review-route items — so the Drive node received '' and threw.
  // v3: the property name reflects only whether a PDF binary EXISTS. Whether we
  //     want to spend an LLM call on it is a separate field, and separate concern.
  const isPdf = !!chosen && chosen.ext === 'pdf';
  const binaryProperty = isPdf ? chosen.binaryProperty : '';
  const extractable = isPdf && !!binaryProperty;

  out.push({
    json: {
      cfg,
      ctx,
      _meta: {
        workflowVersion: cfg.workflowVersion,          // [v3-2]
        source: src.source || 'form',
        recipientEmail: sourceRecipientEmail || null,  // [v3-3]
        runMode,
        liveArmed,
        receivedAt: nowIso(),
        executionId: String($execution.id),
        workflowName: String($workflow.name || ''),
        configErrors,
        configWarnings
      },
      _form: {
        companyRaw: form.companyRaw, roleApplied: form.roleApplied, submittedBy: form.submittedBy,
        notes: form.notes, pastedText: form.pastedText, pastedTextChars: form.pastedTextChars,
        submittedAt: form.submittedAt
      },
      candidate: {
        candidateName, email, phone, roleApplied,
        location: clean(form.location, 120).replace(/[<>"'`\\]/g, ''),
        indeedLink, company: ctx.company, companyKey: ctx.companyKey,
        sourceRecipientEmail: sourceRecipientEmail || ''   // [v3-3]
      },
      _trust: { trusted, reasons, warnings },
      _dedupe: { key: dedupeKey, isDuplicate, isRepeat, enforced: cfg.form.dedupeEnabled, firstSeenAt: prior ? new Date(prior).toISOString() : null },
      _resume: {
        hasAttachment: !!chosen,
        binaryProperty,        // [v3-4] never blanked by route
        extractable,           // [v3-4] the routing-aware flag, used by the IF nodes
        isPdf,
        chosen, accepted, rejected,
        attachmentCount: Object.keys(binary).length
      },
      _driveLinks: { resumePdf: src.resumeDriveLink || null, crawlSnapshot: src.crawlSnapshotDriveLink || null },
      _indeedRelayEmail: src.indeedRelayEmail || null,
      _indeedCandidateId: src.indeedCandidateId || null,
      _gmail: {
        messageId: src.gmailMessageId || null,
        threadId: src.gmailThreadId || null,
        // [v3-3] Which mailbox this message lives in — the Switch that picks the
        // right Gmail credential for 'Mark as Read' reads this. Marking a message
        // read with the wrong mailbox's credential is the exact cause of the
        // recurring Gmail API 404s (§C-1).
        mailbox: sourceRecipientEmail || null
      },
      _route: route,                                   // [v3-1] 'score'|'review'|'auto_reject'
      _autoReject: intakeAutoReject,                   // null unless intake-level policy fired
      _flags: (configWarnings.length ? ['config_warning:' + configWarnings.length] : []).concat(flags),
      _degraded: [],
      _stage: 'intake:' + route
    },
    binary: item.binary,
    pairedItem: i
  });
}
return out;

// ---- shared helpers (inlined; n8n Code nodes do not share scope) ----------------
function safeRequire(name) { try { return require(name); } catch (e) { return null; } }
function sha256Hex(str) {
  const c = safeRequire('crypto');
  if (c && typeof c.createHash === 'function') {
    try { return c.createHash('sha256').update(String(str), 'utf8').digest('hex'); } catch (e) { /* fall through */ }
  }
  const mix = (s, seed) => {
    let h = seed >>> 0;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return ('00000000' + h.toString(16)).slice(-8);
  };
  const s = String(str);
  const r = s.split('').reverse().join('');
  return mix(s, 0x811c9dc5) + mix(r, 0x01000193) + mix(s + r, 0x9e3779b9) + mix(String(s.length) + s, 0x85ebca6b);
}
function maskEmail(addr) {
  const a = String(addr || '').trim();
  if (!a || a.indexOf('@') < 1) return '';
  const [local, domain] = a.split('@');
  if (local.length <= 2) return local[0] + '***@' + domain;
  return local[0] + '***' + local[local.length - 1] + '@' + domain;
}
function maskPhone(p) {
  const d = String(p || '').replace(/\D+/g, '');
  return d.length < 4 ? '' : '***-***-' + d.slice(-4);
}
function clampStr(s, n) {
  const v = (s === null || s === undefined) ? '' : String(s);
  return v.length <= n ? v : v.slice(0, n - 14) + '\n[TRUNCATED]';
}
function asArray(v) { return Array.isArray(v) ? v : (v === null || v === undefined || v === '' ? [] : [v]); }
function nowIso() { return new Date().toISOString(); }
function readEnv(key, fallback) {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[key] : undefined;
    if (v === undefined || v === null || String(v).trim() === '') return fallback;
    return String(v).trim();
  } catch (e) { return fallback; }
}

/**
 * 9 · Normalize CRM & Build Alert
 * ==================================================================================
 * The convergence point. Four upstream paths land here and leave with one shape:
 *   live CRM write   -> HTTP response to classify
 *   dry run / probe   -> no write attempted
 *   review path       -> never scored at all
 *   (any of the above with flags that demand a human)
 *
 * CRM classification: the HubSpot node runs neverError + fullResponse so a 4xx/5xx
 * does not abort the execution. That matters because the Chat alert and the audit log
 * are still worth delivering when the CRM write failed — the hiring owner should hear
 * about a strong candidate whether or not HubSpot was up. batch/upsert can also return
 * 207 Multi-Status; any errored input counts as a failure for this candidate rather
 * than being silently lost.
 *
 * Chat card: Google Chat renders a small HTML subset, so every interpolated value is
 * escaped and every URL is re-validated — a candidate must not be able to inject
 * markup, a fake button, or a link into the hiring channel via their resume.
 */
const out = [];

const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
  .replace(/[​-‏‪-‮﻿]/g, '').slice(0, 900);
// Hand-rolled, not `new URL(...)`: this Code node sandbox has no `URL` global
// (same reason 'Parse Indeed Application Email' hand-rolls its own parser) --
// a real `new URL(...)` call here throws every time and was silently caught,
// so safeUrl() returned '' unconditionally until this fix.
const safeUrl = (u) => {
  const s = String(u === null || u === undefined ? '' : u).trim();
  return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : '';
};
const parseAnyDate = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  const d = /^\d{10,13}$/.test(s) ? new Date(Number(s.length <= 10 ? s + '000' : s)) : new Date(s);
  return isNaN(d.getTime()) ? null : d;
};
const fmtDateTime = (v) => {
  const d = parseAnyDate(v);
  if (!d) return 'Unknown';
  try {
    return d.toLocaleString('en-US', { timeZone: 'America/Chicago', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }) + ' CT';
  } catch (e) { return d.toISOString(); }
};

// CONTEXT IS NEVER READ FROM $input HERE.
// An HTTP Request node with fullResponse emits {body, headers, statusCode} and does
// NOT merge the input JSON. If it fails at the transport layer -- an unset webhook,
// DNS, a timeout -- `neverError` does not apply (that only covers HTTP *status*
// errors) and onError:continueRegularOutput replaces the item with {error} outright.
// Either way the candidate's cfg / ctx / scoring would be gone. Reading the upstream
// nodes back by name is immune to both, and the HTTP response is consulted only for
// what it actually knows: the status of its own call.
const safeAll = (name, branch) => { try { return $(name).all(branch || 0); } catch (e) { return []; } };

const scoredItems = safeAll('6 · Score, Decide & Build Payloads');
const reviewItems = safeAll('3 · Scoreable?', 1);
const crmResponses = safeAll('8 · HubSpot Upsert');

// HubSpot ran only for live-mode items, in scored order — so the k-th response
// belongs to the k-th live item.
const crmFor = {};
let k = 0;
scoredItems.forEach((it, idx) => {
  if (it.json && it.json._crm && it.json._crm.dryRun === false) {
    crmFor[idx] = (crmResponses[k] && crmResponses[k].json) || null;
    k++;
  }
});

const queue = scoredItems.map((it, idx) => ({ json: it.json, crmRes: crmFor[idx] || null, attempted: Object.prototype.hasOwnProperty.call(crmFor, idx) }))
  .concat(reviewItems.map((it) => ({ json: it.json, crmRes: null, attempted: false })));

const inputCount = Math.max(1, $input.all().length);

for (let i = 0; i < queue.length; i++) {
  const json = queue[i].json || {};
  const crmRes = queue[i].crmRes || {};
  const crmAttempted = queue[i].attempted;
  const cfg = json.cfg || { form: {}, runMode: 'unknown', limits: {} };
  const sc = json.scoring || null;
  const flags = asArray(json._flags);
  const scored = !!sc;
  const submittedAt = (json._form && json._form.submittedAt) || null;
  const processedAt = nowIso();

  // ---- 1. CRM result ---------------------------------------------------------------
  let crm = { ok: false, contactId: '', hubspotUrl: '', statusCode: 0, retryable: false, error: null, attemptedAt: nowIso() };
  if (!scored) {
    crm = { ...crm, ok: false, error: 'not attempted — item routed to manual review before scoring', retryable: false, statusCode: null };
  } else if (json._crm && json._crm.dryRun) {
    crm = { ...crm, ok: true, contactId: 'DRY_RUN', statusCode: null };
    flags.push('crm_dry_run_no_write');
  } else if (!crmAttempted) {
    crm = { ...crm, ok: false, error: 'HubSpot node produced no response for this item', retryable: true, statusCode: 0 };
    flags.push('crm_write_failed_retryable');
  } else {
    const transportError = crmRes.error ? (typeof crmRes.error === 'string' ? crmRes.error : (crmRes.error.message || 'request failed')) : null;
    const statusCode = Number(crmRes.statusCode !== undefined ? crmRes.statusCode : (transportError ? 0 : 200));
    const body = (crmRes.body !== undefined && crmRes.body !== null) ? crmRes.body : {};
    const parsedBody = typeof body === 'string' ? (() => { try { return JSON.parse(body); } catch (e) { return { raw: clampStr(body, 500) }; } })() : body;

    let ok = false, contactId = '', errorMessage = null, retryable = false;
    if (transportError) {
      errorMessage = clampStr(transportError, 400);
      retryable = /timeout|ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|EPIPE|socket hang up|network/i.test(transportError);
    } else if (statusCode >= 200 && statusCode < 300) {
      const results = asArray(parsedBody && parsedBody.results);
      const errors = asArray(parsedBody && parsedBody.errors);
      contactId = String((results[0] && results[0].id) || '');
      if (statusCode === 207 || errors.length) { errorMessage = clampStr('multi-status: ' + JSON.stringify(errors).slice(0, 400), 400); }
      else if (contactId) { ok = true; }
      else { errorMessage = 'upsert returned no contact id'; }
    } else {
      const detail = clampStr(JSON.stringify(parsedBody), 500);
      errorMessage = 'HTTP ' + statusCode + ': ' + detail;
      // 429/408/5xx are worth another attempt later; 400/401/403 are config problems.
      retryable = statusCode === 429 || statusCode === 408 || statusCode >= 500;
      if (statusCode === 401 || statusCode === 403) flags.push('crm_auth_failure_check_private_app_token');
      if (statusCode === 400 && /PROPERTY_DOESNT_EXIST|Property .* does not exist/i.test(detail)) flags.push('crm_missing_custom_property_see_runbook');
    }
    if (!ok) flags.push(retryable ? 'crm_write_failed_retryable' : 'crm_write_failed_permanent');
    const portalId = json.ctx.hubspotPortalId;
    crm = {
      ok, contactId, statusCode, retryable, error: errorMessage, attemptedAt: nowIso(),
      hubspotUrl: (ok && contactId && portalId) ? ('https://app.hubspot.com/contacts/' + portalId + '/contact/' + contactId) : ''
    };
  }

  // ---- 2. why a human is needed (review path) --------------------------------------
  const reviewReasons = [];
  if (!scored) {
    const trust = json._trust || { trusted: true, reasons: [] };
    if (!trust.trusted) reviewReasons.push(...asArray(trust.reasons));
    if (json._dedupe && json._dedupe.isDuplicate) reviewReasons.push('duplicate_submission_suppressed');
    if (json.resume && json.resume.sufficient === false) reviewReasons.push('insufficient_resume_content');
    if (flags.includes('pdf_extraction_failed')) reviewReasons.push('pdf_extraction_failed');
    if (flags.some((f) => String(f).startsWith('attachment_format_not_pdf'))) reviewReasons.push('attachment_format_not_pdf');
    if (asArray(json._meta && json._meta.configErrors).length) reviewReasons.push(...asArray(json._meta.configErrors));
    if (!reviewReasons.length) reviewReasons.push('manual_review_required_at_stage:' + String(json._stage || 'unknown'));
  } else if (!crm.ok && !(json._crm && json._crm.dryRun)) {
    reviewReasons.push('crm_write_failed:' + (crm.retryable ? 'retryable' : 'permanent') + ':' + clampStr(crm.error, 200));
  }
  const needsReview = !scored || reviewReasons.length > 0 || (sc && sc.review_status === 'Needs Manual Review');
  const severity = reviewReasons.some((r) => /security|magic_|dangerous|not_allowlisted|access_code|config_error/.test(r)) ? 'HIGH'
    : reviewReasons.some((r) => /crm_write_failed|insufficient_resume|company_not_selected/.test(r)) ? 'MEDIUM' : 'LOW';

  // ---- 3. alert gating -------------------------------------------------------------
  // Scored items only alert when they clear the score threshold; unscored /
  // manual-review items alert only when there's actual content to review.
  // Empty submissions (no resume, no company, no candidate) are silently logged.
  let send = true, suppressReason = '';
  if (scored && sc) {
    // Scorecard gate (language / experience / resume freshness) takes priority: it
    // never touches scoring, CRM, or the audit log -- only whether the channel gets
    // pinged. Checked before the score threshold so its reason is the one recorded
    // when both would have suppressed the same notification.
    if (sc.notify_suppressed_by_gate) {
      send = false;
      suppressReason = 'scorecard_gate_suppressed_notification — see escalation_reasons';
    }
    const minScore = (cfg.thresholds && typeof cfg.thresholds.notifyScoreMin === 'number')
      ? cfg.thresholds.notifyScoreMin
      : 70;
    if (send && typeof sc.total_weighted_score === 'number' && sc.total_weighted_score < minScore) {
      send = false;
      suppressReason = 'below_notify_score_threshold:' + sc.total_weighted_score + '/' + minScore;
    }
  }
  // Suppress notifications for empty/invalid submissions — no resume content,
  // no company, and no candidate name means there's nothing actionable.
  if (send && !scored) {
    const hasResume = (json.resume_chars || 0) > 250 || json._resume?.hasAttachment;
    const hasCompany = json.company && json.company !== 'UNKNOWN';
    const hasCandidate = json.candidate_name || json.candidate_email;
    if (!hasResume && !hasCompany && !hasCandidate) {
      send = false;
      suppressReason = 'empty_submission_no_actionable_data';
    }
  }

  // ---- 4. card ---------------------------------------------------------------------
  const name = (json.candidate && json.candidate.candidateName) || '';
  const company = (json.ctx && json.ctx.company) || 'UNKNOWN';
  let payload;

  if (scored) {
    const icon = sc.recommendation === 'STRONG_FIT' ? '🟢' : sc.recommendation === 'GOOD_FIT' ? '🔵' : sc.recommendation === 'NEEDS_REVIEW' ? '🟠' : '⚪';
    const topStrengths = sc.scores.slice().sort((a, b) => (b.score * b.weight) - (a.score * a.weight)).slice(0, 3).map((s) => '<b>' + esc(s.label) + '</b> ' + esc(s.score) + '/10');
    const weakest = sc.scores.slice().sort((a, b) => (a.score * a.weight) - (b.score * b.weight)).slice(0, 2).map((s) => '<b>' + esc(s.label) + '</b> ' + esc(s.score) + '/10');

    const resumeUrl = safeUrl((json._driveLinks && json._driveLinks.resumePdf) || '');
    const hsUrl = safeUrl(crm.hubspotUrl);
    const inUrl = safeUrl(json.candidate.indeedLink);
    // Neither `<a href>` (shows as literal markup) nor a native `button` object (posted
    // fine but rendered with no clickable action -- this delivery path doesn't seem to
    // support Cards v2 interactivity) actually worked here. Plain bare URLs do: Google
    // Chat auto-linkifies http(s) text on its own, no markup needed. safeUrl() already
    // rejects anything containing <>"'  or whitespace, so the raw string is safe to show
    // as-is. A missing link is still stated, never omitted.
    const resumeCell = resumeUrl || '— not available';
    const hubspotCell = hsUrl
      || ((json._crm && json._crm.dryRun) ? '— not synced (probe mode)' : '— not available' + (crm.error ? (' (' + esc(clampStr(crm.error, 120)) + ')') : ''));
    const indeedCell = inUrl || '— not available';

    const detailRows = [
      { t: 'Role', v: esc(sc.role || 'Not identified') },
      { t: 'Location', v: esc(json.candidate.location || 'Not stated') },
      { t: 'Experience', v: esc(json.structured.years_experience || 0) + ' yrs · avg tenure ' + esc(json.structured.average_tenure_months || 0) + ' mo' },
      { t: 'Contact', v: esc(json.candidate.email || 'Not provided') + (json.candidate.phone ? ' · ' + esc(json.candidate.phone) : '') },
      { t: 'Submitted', v: esc(fmtDateTime(submittedAt)) },
      { t: 'Processed', v: esc(fmtDateTime(processedAt)) },
      { t: '📎 Resume', v: resumeCell },
      { t: '🔗 HubSpot', v: hubspotCell },
      { t: '📋 Indeed', v: indeedCell },
      { t: 'Scorecard', v: esc(sc.scorecard.role) + ' v' + esc(sc.scorecard.version) + (sc.scorecard.source === 'baseline_fallback' ? ' ⚠️ <b>baseline fallback</b>' : '') },
      { t: 'Intake', v: 'form' + (json._form && json._form.submittedBy ? (' by ' + esc(json._form.submittedBy)) : '') },
      { t: 'Strengths', v: topStrengths.join(' · ') || '—' },
      { t: 'Watch', v: weakest.join(' · ') || '—' }
    ];
    if (sc.concerns.length) detailRows.push({ t: 'Concerns', v: sc.concerns.slice(0, 3).map(esc).join('\n') });
    if (sc.escalation_reasons.length) detailRows.push({ t: '⚠️ Review', v: sc.escalation_reasons.slice(0, 5).map(esc).join(', ') });
    if (!crm.ok) detailRows.push({ t: '❌ CRM', v: 'Write failed — ' + esc(clampStr(crm.error, 180)) });

    const sections = [{ widgets: detailRows.map((r) => ({ decoratedText: { topLabel: r.t, text: r.v, wrapText: true } })) }];
    if (sc.summary) sections.push({ header: 'Summary', collapsible: true, uncollapsibleWidgetsCount: 0, widgets: [{ textParagraph: { text: esc(sc.summary) } }] });
    if (sc.suggested_interview_questions.length) sections.push({ header: 'Suggested interview questions', collapsible: true, uncollapsibleWidgetsCount: 0, widgets: [{ textParagraph: { text: sc.suggested_interview_questions.map((q, n) => (n + 1) + '. ' + esc(q)).join('\n') } }] });

    payload = {
      text: icon + ' ' + esc(company) + ' · ' + esc(name || 'Unnamed candidate') + ' — ' + esc(sc.role || 'role unknown') + ' — ' + sc.total_weighted_score + '/100 ' + sc.recommendation,
      cardsV2: [{
        cardId: 'candidate-' + json._meta.executionId + '-' + i,
        card: {
          header: { title: esc(name || 'Unnamed candidate'), subtitle: icon + ' ' + esc(sc.recommendation.replace(/_/g, ' ')) + ' · ' + esc(sc.total_weighted_score) + '/100 · ' + esc(company), imageType: 'CIRCLE' },
          sections
        }
      }]
    };
  } else {
    payload = {
      text: '⚠️ Manual review needed — ' + esc(company) + (name ? (' · ' + esc(name)) : '') + ' [' + severity + ']',
      cardsV2: [{
        cardId: 'review-' + json._meta.executionId + '-' + i,
        card: {
          header: { title: '⚠️ Manual review required', subtitle: esc(company) + ' · severity ' + severity, imageType: 'CIRCLE' },
          sections: (() => {
            const reviewResumeUrl = safeUrl((json._driveLinks && json._driveLinks.resumePdf) || '');
            const reviewIndeedUrl = safeUrl(json.candidate && json.candidate.indeedLink);
            const reviewWidgets = [
            { decoratedText: { topLabel: 'Candidate', text: esc(name || 'unknown') + (json.candidate && json.candidate.roleApplied ? (' — ' + esc(json.candidate.roleApplied)) : ''), wrapText: true } },
            { decoratedText: { topLabel: 'Stage', text: esc(json._stage || 'unknown'), wrapText: true } },
            { decoratedText: { topLabel: 'Reasons', text: reviewReasons.slice(0, 6).map(esc).join('\n'), wrapText: true } },
              { decoratedText: { topLabel: 'Submitted', text: esc(fmtDateTime(submittedAt)), wrapText: true } },
              { decoratedText: { topLabel: 'Processed', text: esc(fmtDateTime(processedAt)), wrapText: true } },
              { decoratedText: { topLabel: '📎 Resume', text: reviewResumeUrl || '— not available', wrapText: true } },
              { decoratedText: { topLabel: '🔗 HubSpot', text: '— not available (not scored)', wrapText: true } },
              { decoratedText: { topLabel: '📋 Indeed', text: reviewIndeedUrl || '— not available', wrapText: true } },
            { decoratedText: { topLabel: 'Submitted by', text: esc((json._form && json._form.submittedBy) || 'anonymous'), wrapText: true } },
            { decoratedText: { topLabel: 'Execution', text: esc(json._meta.executionId), wrapText: true } }
                      ];
            return [{ widgets: reviewWidgets }];
          })()
        }
      }]
    };
  }

  // Per-role hiring-manager Chat space, from the scorecard row (see node 5). Only
  // scored items ever resolve a scorecard, so manual-review items (never scored)
  // and roles that never set the column both fall back to the one space everybody
  // already gets today -- nobody stops receiving alerts because a column is blank.
  const DEFAULT_CHAT_SPACE = 'spaces/AAQABbRdKHM';
  const chatSpaceId = (scored && sc && sc.scorecard && sc.scorecard.hiringManagerChatSpace) || DEFAULT_CHAT_SPACE;

  out.push({
    json: {
      ...json,
      crm,
      _review: { needsReview, severity, reasons: reviewReasons },
      _chat: { payload, send, suppressReason, spaceId: chatSpaceId },
      _flags: Array.from(new Set(flags)),
      _stage: 'delivery:' + (scored ? 'scored' : 'review') + ':' + (crm.ok ? 'crm_ok' : 'crm_none')
    },
    pairedItem: Math.min(i, inputCount - 1)
  });
}
return out;

// =============================================================================
// 5 · Resolve Scorecard & Build Prompt  —  v3  (Code node, typeVersion 2)
// =============================================================================
// CHANGES FROM v2:
//   [v3-1] Reads per-role auto_reject_on_gate_failure + per-gate overrides from
//          the scorecard sheet, and normalises them into scorecard.autoReject.
//   [v3-2] A scorecard row can only NARROW the workflow-level auto-reject policy,
//          never widen it. A sheet editor cannot arm auto-rejection for a
//          workflow that has it switched off. This is the whole security model
//          of putting a business-critical switch in a spreadsheet.
//   [v3-3] Embedded ROLE_ALIASES + EXTRA_SCORECARDS registry so a role missing
//          from the sheet resolves to a real, role-specific scorecard instead of
//          the generic baseline. Ships with the Remote Construction Estimator
//          rules (HVAC / Commercial / Government Bids).
//   [v3-4] Rewritten prompt: EEOC/Title VII hardening, per-execution unpredictable
//          nonce, direct-copy contact extraction, and explicit GATE EVIDENCE
//          fields the deterministic gates in node 6 consume.
//   [v3-5] The baseline fallback can NEVER carry an auto-reject flag. If we do
//          not know the real rubric for a role, we do not reject against it.
// =============================================================================

function safeRequire(name) { try { return require(name); } catch (e) { return null; } }
function sha256Hex(str) {
  const c = safeRequire('crypto');
  if (c && typeof c.createHash === 'function') {
    try { return c.createHash('sha256').update(String(str), 'utf8').digest('hex'); } catch (e) { /* fall through */ }
  }
  const mix = (s, seed) => {
    let h = seed >>> 0;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return ('00000000' + h.toString(16)).slice(-8);
  };
  const s = String(str);
  const r = s.split('').reverse().join('');
  return mix(s, 0x811c9dc5) + mix(r, 0x01000193) + mix(s + r, 0x9e3779b9) + mix(String(s.length) + s, 0x85ebca6b);
}
function clampStr(s, n) {
  const v = (s === null || s === undefined) ? '' : String(s);
  return v.length <= n ? v : v.slice(0, n - 14) + '\n[TRUNCATED]';
}
function asArray(v) { return Array.isArray(v) ? v : (v === null || v === undefined || v === '' ? [] : [v]); }
function nowIso() { return new Date().toISOString(); }

const items = $('3 · Scoreable?').all();

const BASELINE_CRITERIA = [
