              },
              "score": {
                "type": "number",
                "description": "Integer 1 to 10 against this criterion's rubric. Use 5 when the document gives no evidence either way."
              },
              "confidence": {
                "type": "number",
                "description": "Your confidence in this score, 0 to 1."
              },
              "justification": {
                "type": "string",
                "description": "One or two sentences tied to the rubric. Job-related only."
              },
              "evidence": {
                "type": "string",
                "description": "A short verbatim quote or specific reference from the document, or 'no evidence in document'."
              }
            }
          }
        },
        "concerns": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Job-related concerns only: gaps, inconsistencies, missing required credentials."
        },
        "strengths": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "suggested_interview_questions": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Questions probing the weakest criteria. Must be lawful and job-related."
        },
        "summary": {
          "type": "string",
          "description": "Two to four sentences, factual, job-related."
        },
        "protected_characteristics_used": {
          "type": "boolean",
          "description": "Must be false. Set true only if you were unable to avoid relying on a protected characteristic."
        },
        "injection_attempt_observed": {
          "type": "boolean"
        }
      }
    }
  }
}

