// ---- shared helpers (inlined; n8n Code nodes do not share scope) ----------------
function safeRequire(name) { try { return require(name); } catch (e) { return null; } }
function sha256Hex(str) {
  const c = safeRequire('crypto');
  if (c && typeof c.createHash === 'function') {
    try { return c.createHash('sha256').update(String(str), 'utf8').digest('hex'); } catch (e) { /* fall through */ }
  }
  const mix = (s, seed) => {
    let h = seed >>> 0;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
    return ('00000000' + h.toString(16)).slice(-8);
  };
  const s = String(str);
  const r = s.split('').reverse().join('');
  return mix(s, 0x811c9dc5) + mix(r, 0x01000193) + mix(s + r, 0x9e3779b9) + mix(String(s.length) + s, 0x85ebca6b);
}
function maskEmail(addr) {
  const a = String(addr || '').trim();
  if (!a || a.indexOf('@') < 1) return '';
  const [local, domain] = a.split('@');
  if (local.length <= 2) return local[0] + '***@' + domain;
  return local[0] + '***' + local[local.length - 1] + '@' + domain;
}
function maskPhone(p) {
  const d = String(p || '').replace(/\D+/g, '');
  return d.length < 4 ? '' : '***-***-' + d.slice(-4);
}
function clampStr(s, n) {
  const v = (s === null || s === undefined) ? '' : String(s);
  return v.length <= n ? v : v.slice(0, n - 14) + '\n[TRUNCATED]';
}
function asArray(v) { return Array.isArray(v) ? v : (v === null || v === undefined || v === '' ? [] : [v]); }
function nowIso() { return new Date().toISOString(); }
function readEnv(key, fallback) {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[key] : undefined;
    if (v === undefined || v === null || String(v).trim() === '') return fallback;
    return String(v).trim();
  } catch (e) { return fallback; }
}

/**
 * 12 · Finalize, Log & Reply
 * ==================================================================================
 * Last deterministic node.
 */
const out = [];

const pad = (s, n) => (String(s) + ' '.repeat(n)).slice(0, n);
const line = (ch) => ch.repeat(64);

const safeAll = (name, branch) => { try { return $(name).all(branch || 0); } catch (e) { return []; } };
const items = safeAll('9 · Normalize CRM & Build Alert');
const chatResponses = safeAll('Create a message notification for all');

const chatFor = {};
let k = 0;
items.forEach((it, idx) => {
  if (it.json && it.json._chat && it.json._chat.send === true) {
    chatFor[idx] = (chatResponses[k] && chatResponses[k].json) || null;
    k++;
  }
});

const inputCount = Math.max(1, $input.all().length);

for (let i = 0; i < items.length; i++) {
  const json = items[i].json || {};
  const chatRes = chatFor[i] || {};
  const cfg = json.cfg || { sheets: {}, workflowVersion: 'unknown', runMode: 'unknown' };
  const sc = json.scoring || null;
  const flags = Array.from(new Set(asArray(json._flags)));

  const suppressed = !!(json._chat && json._chat.send === false);
  const transportError = chatRes.error ? (typeof chatRes.error === 'string' ? chatRes.error : (chatRes.error.message || 'request failed')) : null;
  const statusCode = Number(chatRes.statusCode !== undefined ? chatRes.statusCode : (transportError ? 0 : 200));
  const chatOk = suppressed || (!transportError && statusCode >= 200 && statusCode < 300);
  if (suppressed) flags.push('chat_alert_suppressed:' + String((json._chat && json._chat.suppressReason) || 'configured'));
  else if (!chatOk) flags.push('chat_alert_failed:' + (transportError ? 'transport' : statusCode));

  const toReviewTab = !sc;
  const row = {
    timestamp: nowIso(),
    execution_id: (json._meta && json._meta.executionId) || String($execution.id),
    workflow_version: cfg.workflowVersion,
    status: sc ? 'scored' : 'not_scored',
    severity: (json._review && json._review.severity) || 'LOW',
    source: (json._meta && json._meta.source) || 'form',
    company: (json.ctx && json.ctx.company) || 'UNKNOWN',
    stage: String(json._stage || ''),
    reasons: asArray(json._review && json._review.reasons).join('; '),
    candidate_name: (json.candidate && json.candidate.candidateName) || '',
    candidate_email: (json.candidate && json.candidate.email) || '',
    candidate_email_indeed_relay: json._indeedRelayEmail || '',
    candidate_email_resume: (json.structured && json.structured.email) || '',
    candidate_phone: (json.candidate && json.candidate.phone) ? ("'" + json.candidate.phone) : '',
    location: (json.candidate && json.candidate.location) || '',
    role_applied: (json.candidate && json.candidate.roleApplied) || '',
    scorecard_role: sc ? sc.scorecard.role : '',
    scorecard_version: sc ? sc.scorecard.version : '',
    scorecard_identity: sc ? sc.scorecard.identity : '',
    scorecard_match_type: sc ? sc.scorecard.matchType : '',
    total_score: sc ? sc.total_weighted_score : '',
    recommendation: sc ? sc.recommendation : '',
    review_status: sc ? sc.review_status : 'Needs Manual Review',
    priority: sc ? sc.priority : '',
    per_criterion_scores: sc ? sc.scores.map((s) => s.criterion + '=' + s.score + '@' + s.weight + '%').join('; ') : '',
    llm_provider: sc ? sc.audit.provider : '',
    llm_model: sc ? sc.audit.model : '',
    llm_temperature: sc ? sc.audit.temperature : '',
    llm_error: sc ? (sc.audit.agent_error || '') : '',
    resume_sha256: (json.resume && json.resume.sha256) || '',
    resume_chars: (json.resume && json.resume.chars) || 0,
    pii_redactions: JSON.stringify((json.resume && json.resume.redactionCounts) || {}),
    injection_neutralizations: (json.resume && json.resume.injectionHits) || 0,
    degraded_mode: sc && sc.audit.degraded_mode ? 'TRUE' : (sc ? 'FALSE' : 'TRUE'),
    degraded_reasons: asArray(json._degraded).join('; '),
    attachment_summary: json._resume ? JSON.stringify({ count: json._resume.attachmentCount, chosen: json._resume.chosen, rejected: json._resume.rejected }).slice(0, 1500) : '',
    indeed_link: (json.candidate && json.candidate.indeedLink) || '',
    flags: flags.join('; '),
    escalation_reasons: sc ? (sc.escalation_reasons || []).join('; ') : '',
    hubspot_contact_id: (json.crm && json.crm.contactId) || '',
    hubspot_ok: (json.crm && json.crm.ok) ? 'TRUE' : 'FALSE',
    chat_alert_ok: chatOk ? 'TRUE' : 'FALSE',
    dedupe_key: (json._dedupe && json._dedupe.key) || '',
    resume_drive_link: (json._driveLinks && json._driveLinks.resumePdf) || '',
    crawl_snapshot_drive_link: (json._driveLinks && json._driveLinks.crawlSnapshot) || ''
  };

  const L = [];
  let title;

  if (sc) {
    const icon = sc.recommendation === 'STRONG_FIT' ? '🟢' : sc.recommendation === 'GOOD_FIT' ? '🔵' : sc.recommendation === 'NEEDS_REVIEW' ? '🟠' : '⚪';
    title = icon + '  ' + sc.total_weighted_score + '/100  —  ' + sc.recommendation.replace(/_/g, ' ');

    L.push(line('='), 'CANDIDATE', line('='));
    L.push('Name        : ' + (json.candidate.candidateName || '(not supplied)'));
    L.push('Role        : ' + (json.candidate.roleApplied || '(not supplied)'));
    L.push('Company     : ' + json.ctx.company);
    L.push('Location    : ' + (json.candidate.location || '(not supplied)'));
    L.push('Email       : ' + (json.candidate.email || '(not supplied)'));
    L.push('Experience  : ' + (json.structured.years_experience || 0) + ' yrs, average tenure ' + (json.structured.average_tenure_months || 0) + ' months');
    if (asArray(json.structured.certifications).length) L.push('Certs       : ' + json.structured.certifications.join(', '));
    L.push('');

    L.push(line('='), 'SCORE  ' + sc.total_weighted_score + '/100  (' + sc.recommendation + ', priority ' + sc.priority + ')', line('='));
    L.push('Scorecard   : ' + sc.scorecard.role + ' v' + sc.scorecard.version + '  [' + sc.scorecard.source + ', match=' + sc.scorecard.matchType + ']');
    if (sc.scorecard.source === 'baseline_fallback') {
      L.push('              NOTE: no scorecard matched this role, so the built-in baseline');
      L.push('              was used. Add the role to your scorecard sheet for real scoring.');
    }
    L.push('');
    for (const s of sc.scores) {
      L.push(pad(s.label, 26) + pad(s.weight + '%', 6) + pad(s.score + '/10', 7) + (s.defaulted ? '(defaulted)' : ''));
      if (s.justification) L.push('    ' + clampStr(s.justification, 260));
      if (s.evidence && s.evidence !== 'no evidence in document') L.push('    evidence: ' + clampStr(s.evidence, 200));
      L.push('');
    }

    if (sc.summary) { L.push(line('-'), 'SUMMARY', line('-'), sc.summary, ''); }
    if (asArray(sc.strengths).length) { L.push('STRENGTHS'); sc.strengths.forEach((s) => L.push('  + ' + s)); L.push(''); }
    if (asArray(sc.concerns).length) { L.push('CONCERNS'); sc.concerns.forEach((s) => L.push('  ! ' + s)); L.push(''); }
    if (asArray(sc.suggested_interview_questions).length) {
      L.push('SUGGESTED INTERVIEW QUESTIONS');
      sc.suggested_interview_questions.forEach((q, n) => L.push('  ' + (n + 1) + '. ' + q));
      L.push('');
    }

    L.push(line('='), 'INGESTION DIAGNOSTICS   (this is the part to sanity-check)', line('='));
    const r = json.resume || {};
    L.push('Resume source     : ' + ([r.sources && r.sources.pdf ? 'PDF attachment' : null, r.sources && r.sources.pasted ? 'pasted text' : null].filter(Boolean).join(' + ') || 'none'));
    L.push('Characters used   : ' + (r.chars || 0) + (r.originalChars && r.originalChars !== r.chars ? ('  (truncated from ' + r.originalChars + ')') : ''));
    L.push('PDF pages         : ' + (r.pages || 0));
    L.push('Fingerprint       : ' + String(r.sha256 || '').slice(0, 24));
    L.push('PII redactions    : ' + (r.redactionTotal || 0) + '  ' + JSON.stringify(r.redactionCounts || {}));
    L.push('Injection defused : ' + (r.injectionHits || 0));
    L.push('Language flag     : ' + (r.likelyNonEnglish ? 'possibly NOT English' : 'looks English'));
    L.push('Model             : ' + sc.audit.provider + ' / ' + sc.audit.model + ' (temp ' + sc.audit.temperature + ')');
    L.push('Extraction        : ' + (sc.audit.extraction_ok ? 'ok' : 'FAILED') + '   Scoring: ' + (sc.audit.scoring_ok ? 'ok' : 'FAILED'));
    if (sc.audit.agent_error) L.push('Model error       : ' + sc.audit.agent_error);
    L.push('Degraded mode     : ' + (sc.audit.degraded_mode ? 'YES — ' + asArray(sc.audit.degraded_reasons).join(', ') : 'no'));
    L.push('');

    L.push(line('='), 'DELIVERY', line('='));
    L.push('Run mode          : ' + cfg.runMode + (cfg.runMode !== 'live' ? '  (no CRM write performed)' : ''));
    L.push('HubSpot           : ' + (json.crm && json.crm.ok ? (json.crm.contactId === 'DRY_RUN' ? 'skipped (dry run / probe)' : 'contact ' + json.crm.contactId) : 'FAILED — ' + clampStr((json.crm && json.crm.error) || 'unknown', 200)));
    L.push('Chat alert        : ' + (suppressed ? 'suppressed' : chatOk ? 'sent' : 'failed'));
    L.push('Review status     : ' + sc.review_status);
    if (asArray(sc.escalation_reasons).length) {
      L.push('', 'ESCALATED FOR HUMAN REVIEW because:');
      sc.escalation_reasons.forEach((x) => L.push('  - ' + x));
    }
  } else if (json._dedupe && json._dedupe.isDuplicate) {
    title = '↩︎  Duplicate submission — not scored again';
    L.push('This resume was already processed at ' + (json._dedupe.firstSeenAt || 'an earlier time') + '.');
    L.push('');
    L.push('It was skipped to avoid a duplicate CRM record and a duplicate scoring charge.');
    L.push('If you are testing and want repeat submissions to score every time, leave');
    L.push('FORM_DEDUPE_ENABLED unset (the default is off).');
    L.push('');
    L.push('Fingerprint: ' + String(json._dedupe.key || '').slice(0, 48));
  } else {
    const reasons = asArray(json._review && json._review.reasons);
    const severity = (json._review && json._review.severity) || 'MEDIUM';
    title = '⚠︎  Not scored — needs attention (' + severity + ')';
    L.push('The submission was accepted but could not be scored. Nothing was lost: it is');
    L.push('recorded in the manual review queue and announced in the hiring channel.');
    L.push('', line('='), 'WHY', line('='));
    reasons.forEach((r) => L.push('  - ' + r));
    L.push('', line('='), 'WHAT TO DO', line('='));
    const rs = reasons.join(' ');
    const before = L.length;
    if (/no_resume_file_and_no_pasted_text/.test(rs)) {
      L.push('  Attach a resume file, or paste the resume text into the text box. One of');
      L.push('  the two is required.');
    }
    if (/insufficient_resume_content/.test(rs)) {
      L.push('  Too little text was recovered to score fairly. If you uploaded a .docx or a');
      L.push('  scanned/image PDF, the text extractor cannot read it — open the file, copy');
      L.push('  the text, and paste it into the "Resume Text" box instead.');
    }
    if (/pdf_extraction_failed|attachment_format_not_pdf/.test(rs)) {
      L.push('  The document could not be read (encrypted, scanned, or not a real PDF).');
      L.push('  Paste the resume text instead.');
    }
    if (/access_code_invalid/.test(rs)) L.push('  The access code was wrong. Check it with whoever set up this form.');
    if (/rate_limit_exceeded/.test(rs)) L.push('  The hourly submission limit was reached. Wait an hour or raise FORM_MAX_PER_HOUR.');
    if (/company_not_selected/.test(rs)) L.push('  Pick a company from the dropdown.');
    if (/crm_write_failed/.test(rs)) L.push('  The candidate WAS scored; only the HubSpot write failed. See the score above and the review queue row.');
    if (/config_error/.test(rs)) {
      L.push('  The workflow itself is misconfigured — this is not your submission\'s fault.');
      L.push('  Set INTAKE_RUN_MODE=probe to test without Sheets/HubSpot, or configure the');
      L.push('  missing environment variables listed above.');
    }
    if (L.length === before) L.push('  See the manual review queue row for this execution.');
    L.push('');
    L.push('Execution: ' + row.execution_id);
  }

  if (flags.length) {
    L.push('', line('-'), 'ALL FLAGS (' + flags.length + ')', line('-'));
    flags.forEach((f) => L.push('  · ' + f));
  }

  out.push({
    json: {
      ...row,
      flags: flags.join('; '),
      _sheets: {
        spreadsheetId: cfg.sheets.opsSpreadsheetId,
        tab: toReviewTab ? cfg.sheets.reviewTab : cfg.sheets.auditTab
      },
      _formResponse: { title: clampStr(title, 200), message: clampStr(L.join('\n'), 12000) },
      _gmail: json._gmail || { messageId: null, threadId: null },
      _stage: 'finalized'
    },
    pairedItem: Math.min(i, inputCount - 1)
  });
}
return out;

/**
 * E2 · Format Error
 * ==================================================================================
 * Fires via the Error Trigger for anything that escaped the per-node handling above
 * (an n8n-level fault, a revoked credential, an out-of-memory kill). Two jobs:
 *
 *  1. Make the failure loud — a Sheet row plus a Chat message, never a silent red
 *     execution sitting in a list nobody watches.
 *  2. Scrub the payload before it is written anywhere. Error contexts routinely carry
 *     request bodies and headers, which is exactly where API keys, bearer tokens and
 *     candidate PII live. Anything that looks like a secret is masked and the whole
 *     blob is length-capped.
 */
const SECRET_PATTERNS = [
  [/\b(sk-[A-Za-z0-9_\-]{12,})/g, 'sk-[REDACTED]'],
  [/\b(sk-ant-[A-Za-z0-9_\-]{12,})/g, 'sk-ant-[REDACTED]'],
  [/\b(pat-[a-z0-9\-]{8,})/gi, 'pat-[REDACTED]'],
  [/\b(xox[baprs]-[A-Za-z0-9\-]{8,})/g, 'xox-[REDACTED]'],
  [/\b(gh[pousr]_[A-Za-z0-9]{20,})/g, 'gh_[REDACTED]'],
  [/\b(ya29\.[A-Za-z0-9_\-]{20,})/g, 'ya29.[REDACTED]'],
  [/(eyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{6,})/g, '[JWT_REDACTED]'],
  [/((?:authorization|x-api-key|api[-_]?key|bearer|token|secret|password|passwd|client[-_]?secret|private[-_]?key)["'\s:=]+)([^\s",}]{6,})/gi, '$1[REDACTED]'],
  [/(https:\/\/chat\.googleapis\.com\/v1\/spaces\/[^\s"']*)/g, 'https://chat.googleapis.com/v1/spaces/[REDACTED]'],
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, '[PRIVATE_KEY_REDACTED]'],
  [/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,24}/g, '[EMAIL_REDACTED]'],
  [/\b(?!000|666|9\d\d)\d{3}[ -]?(?!00)\d{2}[ -]?(?!0000)\d{4}\b/g, '[SSN_REDACTED]']
];
const scrub = (s) => { let v = String(s === null || s === undefined ? '' : s); for (const [re, rep] of SECRET_PATTERNS) v = v.replace(re, rep); return v; };
const cap = (s, n) => { const v = scrub(s); return v.length <= n ? v : v.slice(0, n) + '…[TRUNCATED]'; };
const readEnv = (key, fallback) => {
  try { const v = (typeof $env !== 'undefined' && $env) ? $env[key] : undefined; return (v === undefined || v === null || String(v).trim() === '') ? fallback : String(v).trim(); } catch (e) { return fallback; }
};

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const json = items[i].json || {};
  const wf = json.workflow || {};
  const ex = json.execution || {};
  const err = ex.error || json.error || {};
  const lastNode = (ex.lastNodeExecuted || (err.node && (err.node.name || err.node)) || 'unknown');
  const message = cap(err.message || err.description || 'unknown error', 1000);

  out.push({
    json: {
      _sheets: {
        spreadsheetId: readEnv('SHEET_ID_OPS', 'YOUR_GOOGLE_FILE_ID'),
        tab: readEnv('SHEET_TAB_ERRORS', 'error_log')
      },
      timestamp: new Date().toISOString(),
      workflow_id: String(wf.id || ''),
      workflow_name: String(wf.name || ''),
      execution_id: String(ex.id || ''),
      execution_url: String(ex.url || ''),
      execution_mode: String(ex.mode || ''),
      retry_of: String(ex.retryOf || ''),
      failed_node: String(lastNode),
      error_name: String(err.name || 'Error'),
      error_message: message,
      error_context: (() => { try { return cap(JSON.stringify(err.context || {}), 1500); } catch (e) { return ''; } })(),
      stack_excerpt: cap(err.stack || '', 2500),
      severity: /credential|unauthor|forbidden|401|403/i.test(message) ? 'HIGH' : 'MEDIUM',
      chat_text: '🚨 Indeed resume intake workflow FAILED\n• Workflow: ' + String(wf.name || 'unknown')
        + '\n• Failed node: ' + String(lastNode)
        + '\n• Error: ' + message.slice(0, 400)
        + '\n• Execution: ' + String(ex.url || ex.id || 'n/a')
        + '\n\nNothing is auto-rejected and nothing is deleted — resubmit the affected resumes once this is fixed.'
    },
    pairedItem: i
  });
}
return out;

// Adapts the Firecrawl-scraped, markdown-extracted resume ("Code in JavaScript" node
// output) back into the original Indeed application context — recovered via
// itemMatching (NOT positional indexing) because the Route switch upstream can send
// only SOME items down this branch, so a local index here does not equal the global
// index at "Parse Indeed Application Email" — and into the field shape the Form
// Trigger produces. Also picks up the Drive links for the rebuilt PDF and the raw
// crawl snapshot, if those branches produced them for this item.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const scraped = items[i].json || {};
  const candidate = scraped.candidate || {};

  let src = {};
  try { const m = $('Parse Indeed Application Email').itemMatching(i); src = (m && m.json) || {}; } catch (e) { src = {}; }

  let resumeDriveLink = null;
  try { const m = $('Upload Rebuilt Resume PDF to Drive').itemMatching(i); resumeDriveLink = (m && m.json && (m.json.webViewLink || m.json.webContentLink)) || null; } catch (e) { /* branch didn't run for this item, or upload failed */ }

  let crawlSnapshotDriveLink = null;
  try { const m = $('Upload Raw Crawl to Drive').itemMatching(i); crawlSnapshotDriveLink = (m && m.json && (m.json.webViewLink || m.json.webContentLink)) || null; } catch (e) { /* same */ }

  const notes = [];
  if (candidate.linkedIn) notes.push('LinkedIn: ' + candidate.linkedIn);
  if (candidate.github) notes.push('GitHub: ' + candidate.github);
  if (candidate.portfolio) notes.push('Portfolio: ' + candidate.portfolio);
  if (!scraped.success) notes.push('Resume scrape did not fully succeed — verify manually.');

  out.push({
    json: {
      source: 'indeed_gmail',
      submittedAt: src.received_at || null,
      'Company': src.company || '',
      'Role Applied For': src.job_title || '',
      'Candidate Name': candidate.name || src.candidate_name || '',
      'Candidate Email': candidate.email || src.indeed_relay_email || '',
      'Candidate Phone': candidate.phone || '',
      'Location': src.job_location || '',
      'Indeed Application URL': src.fetch_url || src.view_url || src.resume_url || '',
      'Submitted By': 'Indeed automation (Gmail)',
      'Notes': notes.join(' | '),
      'Resume Text': scraped.success ? String(scraped.resumeMarkdown || scraped.rawText || '') : '',
      resumeDriveLink,
      crawlSnapshotDriveLink,
      gmailMessageId: src.message_id || null,
      indeedRelayEmail: src.indeed_relay_email || null,
      indeedCandidateId: src.candidate_id || null,
      gmailThreadId: src.thread_id || null,
      _indeedMeta: {
        messageId: src.message_id || null,
        employerId: src.employer_id || null,
        candidateId: src.candidate_id || null,
        scrapeSuccess: !!scraped.success
      }
    }
  });
}
return out;

// The Drive node's output replaced $json with the Drive API response, discarding the
// original intake context and binary. Recover both from "1 · Intake, Config & Guard"
// via itemMatching (safe across the IF branch above) and attach the resulting link.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const driveResp = items[i].json || {};
  let orig = null;
  try { orig = $('1 · Intake, Config & Guard').itemMatching(i); } catch (e) { orig = null; }
  const origJson = (orig && orig.json) || {};
  const origBinary = (orig && orig.binary) || {};
  out.push({
    json: {
      ...origJson,
      _driveLinks: { ...(origJson._driveLinks || {}), resumePdf: driveResp.webViewLink || driveResp.webContentLink || null },
      resumeDriveFileId: driveResp.id || null
    },
    binary: origBinary,
    pairedItem: i
  });
}
return out;

// Snapshot the raw Firecrawl HTML capture for audit/debugging, independent of
// whether downstream text-extraction succeeds.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const html = (j.data && j.data.html) || j.html || '';
  const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(html || '(no html captured)', 'utf8'),
    'raw_crawl_' + String($execution.id) + '_' + i + '.html',
    'text/html'
  );
  out.push({ json: { hasHtml: !!html, htmlChars: html.length }, binary: { data: binaryData }, pairedItem: i });
}
return out;

// n8n Code Node: Extract PDF Download URL (does not download the file itself)
// Never throws: returns success:false when the link can't be found, so the
// workflow falls back to the scrape-and-reconstruct path instead of aborting
// the whole execution.
//
// Runs downstream of "Upload Raw Crawl to Drive" (not directly off "Edit Fields")
// so that node's Drive link becomes a genuine ancestor reachable via itemMatching
// from everything below this point. itemMatching can only trace backward through a
// real ancestor chain, not sideways across sibling branches -- which is exactly why
// the raw crawl link was landing as null further downstream before this was chained
// in this way. Recovers the actual scraped HTML via itemMatching against "Edit
// Fields" since this node's own immediate input is now the Drive upload's response,
// not the scrape result.
const items = $input.all();
const returnData = [];

for (let i = 0; i < items.length; i++) {
  let editJson = {};
  try { const m = $('Edit Fields').itemMatching(i); editJson = (m && m.json) || {}; } catch (e) { editJson = {}; }
  const html = editJson?.data?.html || editJson?.html || '';

  if (!html) {
    returnData.push({ json: { success: false, reason: 'no_html_in_payload' }, pairedItem: i });
    continue;
  }

  const downloadUrlMatch = html.match(/href="([^"]*public\/resume\/download[^"]*)"/i);
  if (!downloadUrlMatch) {
    returnData.push({ json: { success: false, reason: 'no_download_link_found' }, pairedItem: i });
    continue;
  }

  const pdfUrl = downloadUrlMatch[1].replace(/&amp;/g, '&');

  const nameMatch = html.match(/<span class="[^"]*e1wnkr790[^"]*">([\s\S]*?)<\/span>/i);
  let fileName = 'resume.pdf';
  if (nameMatch) {
    const rawName = nameMatch[1].replace(/'s Resume/gi, '').trim();
    if (rawName) fileName = rawName.replace(/[^a-zA-Z0-9_\-]/g, '_') + '_resume.pdf';
  }

  returnData.push({ json: { success: true, fileName, downloadUrl: pdfUrl }, pairedItem: i });
}

return returnData;

// Primary resume-acquisition path: the actual, original PDF downloaded directly
// from Indeed's own public download URL (found by "Get direct download link of
// resume"). Byte-perfect -- no HTML-scrape reconstruction involved. Recovers
// application context (company, role applied for, candidate identity) from
// "Parse Indeed Application Email" via itemMatching, since several nodes sit
// between that node and this one. The Parse node's fields are treated as the
// authoritative reference for what the candidate actually applied for.
//
// "Archive Raw Crawl HTML" -> "Upload Raw Crawl to Drive" runs unconditionally for
// every link-based application, regardless of whether THIS (direct download) path
// or the scrape fallback ends up winning -- so even on this path there is a raw
// crawl snapshot to link back to, recovered here the same way the fallback bridge
// already does it.
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const binary = items[i].binary || {};

  let src = {};
  try { const m = $('Parse Indeed Application Email').itemMatching(i); src = (m && m.json) || {}; } catch (e) { src = {}; }

  let linkInfo = {};
  try { const m = $('Get direct download link of resume').itemMatching(i); linkInfo = (m && m.json) || {}; } catch (e) { linkInfo = {}; }

  let crawlSnapshotDriveLink = null;
  try { const m = $('Upload Raw Crawl to Drive').itemMatching(i); crawlSnapshotDriveLink = (m && m.json && (m.json.webViewLink || m.json.webContentLink)) || null; } catch (e) { /* archive branch didn't run for this item, or upload failed */ }

  // Force correct file metadata so node 1's attachment classifier recognizes
  // this as a PDF regardless of what headers Indeed's download endpoint sent.
  const pdfFileName = String(linkInfo.fileName || 'resume.pdf').replace(/[^a-zA-Z0-9_\-.]/g, '_');
  const fixedBinary = {};
  if (binary.data) {
    fixedBinary.data = { ...binary.data, fileName: pdfFileName, fileExtension: 'pdf', mimeType: 'application/pdf' };
  }

  out.push({
    json: {
      source: 'indeed_gmail',
      submittedAt: src.received_at || null,
      gmailMessageId: src.message_id || null,
      gmailThreadId: src.thread_id || null,
      indeedRelayEmail: src.indeed_relay_email || null,
      indeedCandidateId: src.candidate_id || null,
      crawlSnapshotDriveLink,
      'Company': src.company || '',
      'Role Applied For': src.job_title || '',
      'Candidate Name': src.candidate_name || '',
      'Candidate Email': src.indeed_relay_email || '',
      'Location': src.job_location || '',
      'Indeed Application URL': src.fetch_url || src.view_url || src.resume_url || '',
      'Submitted By': 'Indeed automation (Gmail) — direct download',
      'Notes': 'Original resume PDF downloaded directly from Indeed (highest-fidelity source; scrape-based paths are the fallback).',
      'Resume Text': '',
      _indeedMeta: {
        messageId: src.message_id || null,
        threadId: src.thread_id || null,
        employerId: src.employer_id || null,
        candidateId: src.candidate_id || null,
        directDownload: true
      }
    },
    binary: fixedBinary
  });
}

return out;

// =============================================================================
// Build D1 Mirror Row  —  v3  (Code node, typeVersion 2)
// =============================================================================
// CHANGES FROM v2:
//   [v3-1] BOOLEANS ARE NOW INTEGERS. v2 sent String('TRUE')/String('FALSE')
//          into columns declared INTEGER DEFAULT 0. SQLite's loose typing stored
//          them as TEXT, so `WHERE hubspot_ok = 1` matches ZERO rows — verified
//          against the live table: 38/38 rows hold TEXT in both boolean columns.
//   [v3-2] candidate_email is emitted AND inserted. v2 built the field and then
//          left it out of the INSERT column list, so it was silently discarded.
//   [v3-3] All auto-reject / routing / provenance columns added.
//   [v3-4] lead_id is made collision-safe. It is the PRIMARY KEY, and v2 fell
//          back to dedupe_key when the Indeed candidate id was absent — two
//          different applications from the same person to the same role produced
//          the same key and the second INSERT failed the UNIQUE constraint. With
//          neverError:true that failure was invisible and the row was lost.
// =============================================================================
const out = [];
const items = $input.all();

const b = (v) => (v === true || v === 1 || v === '1' || String(v).toUpperCase() === 'TRUE') ? 1 : 0;  // [v3-1]
const s = (v) => (v === null || v === undefined) ? '' : String(v);
const n = (v) => { const x = Number(v); return Number.isFinite(x) ? x : null; };

for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};

  let ctx = {};
  try { const m = $('9 · Normalize CRM & Build Alert').itemMatching(i); ctx = (m && m.json) || {}; } catch (e) { ctx = {}; }

  const sc = ctx.scoring || null;
  const ar = (sc && sc.auto_reject) || null;

  const phoneRaw = (ctx.candidate && ctx.candidate.phone) || (ctx.structured && ctx.structured.phone) || '';
  const phoneDigits = String(phoneRaw).replace(/\D+/g, '');
  const phone = phoneDigits.length > 10 ? phoneDigits.slice(-10) : phoneDigits;

  // [v3-4] Stable, collision-safe primary key.
  // Preference order: Indeed's own candidate id (globally unique, survives
  // re-processing of the same application) > resume fingerprint + role (same
  // document, same role => same lead, which is what an UPSERT should collapse)
  // > dedupe key > execution-scoped fallback that can never collide.
  const leadId = ctx._indeedCandidateId
    || (row.resume_sha256 && row.role_applied ? ('sha:' + String(row.resume_sha256).slice(0, 32) + ':' + String(row.role_applied).toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 40)) : '')
    || row.dedupe_key
    || ('exec:' + s(row.execution_id) + ':' + i);

  const now = new Date().toISOString();

  out.push({
    json: {
      lead_id: leadId,
      created_time: row.timestamp || now,
      updated_at: now,
      synced_at: now,
      job_title: s(row.role_applied),
      full_name: s(row.candidate_name),
      phone, phone_raw: s(phoneRaw),
      source: s(row.source),
      source_recipient_email: s(row.source_recipient_email),           // [§C-2]
      company: s(row.company),
      candidate_email: s(row.candidate_email || row.candidate_email_resume || row.candidate_email_indeed_relay), // [v3-2]
      candidate_email_indeed_relay: s(row.candidate_email_indeed_relay),
      candidate_email_resume: s(row.candidate_email_resume),
      scorecard_role: s(row.scorecard_role),
      scorecard_version: s(row.scorecard_version),
      scorecard_identity: s(row.scorecard_identity),
      scorecard_match_type: s(row.scorecard_match_type),
      total_score: n(row.total_score),
      recommendation: s(row.recommendation),
      review_status: s(row.review_status),
      priority: s(row.priority),

      // [v3-3] routing + auto-rejection
      route: s(row.route || (ar && ar.applied ? 'auto_reject' : sc ? 'score' : 'review')),
      auto_reject: b(ar && ar.applied),
      auto_reject_gate: s(ar && ar.gate),
      auto_reject_rule: s(ar && ar.rule),
      auto_reject_reason: s(ar && ar.reason),
      gate_evaluations: JSON.stringify((sc && sc.gate_evaluations) || []).slice(0, 4000),
      notify_suppressed: b(row.notify_suppressed === 'TRUE' || row.notify_suppressed === true),
      notify_channel: s(row.notify_channel),

      per_criterion_scores: s(row.per_criterion_scores),
      llm_provider: s(row.llm_provider),
      llm_model: s(row.llm_model),
      llm_temperature: n(row.llm_temperature),
      llm_error: s(row.llm_error),
      resume_sha256: s(row.resume_sha256),
      hubspot_contact_id: s(row.hubspot_contact_id),
      hubspot_ok: b(row.hubspot_ok),                                   // [v3-1]
      chat_alert_ok: b(row.chat_alert_ok),                             // [v3-1]
      degraded_mode: b(row.degraded_mode),
      escalation_reasons: s(row.escalation_reasons).slice(0, 2000),
      resume_drive_link: s(row.resume_drive_link),
      crawl_snapshot_drive_link: s(row.crawl_snapshot_drive_link),
      workflow_version: s(row.workflow_version),
      execution_id: s(row.execution_id),
      _sheets: JSON.stringify(row._sheets || {}),
      _formResponse: JSON.stringify(row._formResponse || {}),

      // carried for the HTTP node's URL/table expression, not inserted
      _d1: {
        accountId: (ctx.cfg && ctx.cfg.d1 && ctx.cfg.d1.accountId) || '',
        databaseId: (ctx.cfg && ctx.cfg.d1 && ctx.cfg.d1.databaseId) || '',
        table: (ctx.cfg && ctx.cfg.d1 && ctx.cfg.d1.table) || 'indeed_leads_staging_v3'
      }
    },
    pairedItem: i
  });
}
return out;

// Google Sheets (USER_ENTERED input mode) treats a value starting with '+', '=',
// '-', or '@' as the start of a formula -- which is exactly what turned phone_raw
// values like "+63+1 555-0100" into #ERROR!. Cloudflare D1 has no such quirk, so
// this escaping is applied only on this Sheets-bound branch, never on the data sent
// to "Push to Cloudflare D1", which reads directly from "Build D1 Mirror Row"
// upstream of this node and is unaffected by it.
const out = [];
const items = $input.all();
const escapeForSheets = (v) => {
  const s = String(v === null || v === undefined ? '' : v);
  return /^[+=\-@]/.test(s) ? ("'" + s) : s;
};
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  out.push({
    json: {
      ...row,
      phone: escapeForSheets(row.phone),
      phone_raw: escapeForSheets(row.phone_raw)
    },
    pairedItem: i
  });
}
return out;

// =============================================================================
// ⚙️ Workflow Config  —  v3  (Code node, typeVersion 2)
// =============================================================================
// v5.0.0-v3-auto-reject
//
// WHAT CHANGED FROM v2
//   1. workflowVersion is now DECLARED HERE and read downstream. In v2 node 1
//      hard-coded '4.0.0-agent' and ignored the config node entirely, so every
//      audit row, CRM property and D1 mirror row recorded a version that no
//      longer matched the deployed code. Version now has exactly one source.
//   2. runMode carries a THREE-STATE transition (O-6): 'probe' | 'dry_run' |
//      'live'. `liveArmed` is a second, independent switch — runMode must be
//      'live' AND liveArmed must be true before a single byte reaches HubSpot.
//      Flipping one is reversible in isolation; that is the entire point.
//   3. Auto-rejection master switch + per-gate policy (new in v3).
//   4. v3-isolated write targets: audit_log_v3 / manual_review_v3 /
//      auto_reject_log_v3 / error_log_v3 and indeed_leads_staging_v3, so a v3
//      test execution can never land in a tab or table v2 [PROD] is using.
//
// ENVIRONMENT NOTE: this n8n host denies $env in expressions AND in the Code
// sandbox. Every value therefore lives here, in the workflow, under version
// control — never in an environment variable that silently resolves to ''.
// =============================================================================

const CONFIG = {
  // ---- identity -------------------------------------------------------------
  workflowVersion: '5.0.0-v3-auto-reject',
  environment: 'prod',            // 'test' | 'prod_staging' | 'prod'

  // ---- run mode (O-6) -------------------------------------------------------
  // probe    : no CRM write, no Chat send to hiring spaces, v3 tabs only.
  // dry_run  : full pipeline incl. Chat, CRM payload BUILT and logged, not sent.
  // live     : CRM writes execute — but ONLY if liveArmed is also true.
  runMode: 'live',
  liveArmed: true,               // second key in the two-key launch. See §G.

  // ---- data stores ----------------------------------------------------------
  scorecardSpreadsheetId: 'YOUR_GOOGLE_FILE_ID',
  opsSpreadsheetId: 'YOUR_GOOGLE_FILE_ID',
  auditTab: 'audit_log',           // v2 writes 'audit_log' — do not collide
  reviewTab: 'manual_review_queue',      // v2 writes 'manual_review_queue'
  autoRejectTab: 'auto_reject_log',// new in v3
  errorTab: 'error_log',
  d1MirrorSheetGid: '+1 555-0100',

  // Cloudflare D1
  d1AccountId: 'bd33772c7e6ca6634b9f1fdeabeb6a1f',
  d1DatabaseId: 'YOUR_GOOGLE_FILE_ID',
  d1Table: 'indeed_leads_staging',  // PROD cutover flips this to indeed_leads_staging

  // ---- LLM ------------------------------------------------------------------
  // These three MUST match the attached model sub-node. In v2 the config said
  // google_vertex / gemini-2.5-flash / 0 while the attached node was actually
  // models/gemini-3.5-flash-lite at temperature 0.1 — so every audit row and
  // every ai_model_used CRM property named a model that never ran. For an
  // EEOC-defensible audit trail that mismatch is not cosmetic.
  llmProvider: 'google_gemini',
  llmModel: 'models/gemini-3.5-flash-lite',
  llmTemperature: 0.1,
  llmMaxOutputTokens: 70000,

  // ---- scoring thresholds ---------------------------------------------------
  strongFit: 80,
  goodFit: 65,
  needsReview: 50,
  notifyScoreMin: 50,

  // ---- AUTO-REJECTION POLICY (new in v3) ------------------------------------
  // Master kill switch. false => v3 behaves exactly like v2: a gate failure only
  // suppresses the Chat ping, the candidate is still scored, logged and upserted.
  autoRejectEnabled: true,

  // Per-gate defaults. A scorecard row's own auto_reject_on_gate_failure column
  // can only ever NARROW these, never widen them (see node 5). Absent column =>
  // fall back to these values.
  autoRejectOnLanguageGate: true,
  autoRejectOnExperienceGate: true,
  autoRejectOnResumeAgeGate: false,   // staleness is the weakest signal — review, don't reject

  // HARD SAFETY RAILS. These are checked in node 6 and cannot be overridden by
  // any scorecard row. A gate may only fire when the evidence it rests on is
  // actually trustworthy.
  autoRejectMinExtractionConfidence: 0.55,
  autoRejectRequireScoringOk: true,   // never auto-reject a degraded/failed LLM run
  autoRejectRequireResumeDoc: true,   // never auto-reject if document_is_resume === false
  autoRejectExperienceShortfallPct: 0.25, // must miss by >25%, not the 10% notify threshold
  autoRejectMaxPerHourPerCompany: 25, // circuit breaker: above this, degrade to review

  // ---- notification routing (new in v3) -------------------------------------
  chatSpaceHiringDefault: 'spaces/AAQABbRdKHM',
  chatSpaceAllNotifications: 'spaces/AAQA5Do_zwM',
  chatSpaceAudit: 'spaces/AAQA5Do_zwM',   // auto-rejects land here, NOT in hiring spaces
  autoRejectNotifyHiringManager: false,   // §B: keep hiring spaces uncluttered
  alertsEnabled: true,

  // ---- limits / security ----------------------------------------------------
  maxResumeChars: 60000,
  minResumeChars: 250,
  maxPdfPages: 15,
  maxAttachmentBytes: 15728640,
  maxPerHour: 20,
  dedupeEnabled: false,
  dedupeTtlHours: 168,
  dedupeMaxKeys: 5000,
  accessCodeRequired: false,
  redactPii: true,
  neutralizePromptInjection: true,

  // ---- HubSpot --------------------------------------------------------------
  // Auth is NO LONGER an $env expression (that resolved to 'Bearer ' on this
  // host — a guaranteed 401 the moment runMode went live). v3 routes through
  // two Header Auth credentials selected by a Switch on ctx.companyKey.
  hubspotEnabled: false,
  hubspotDryRun: true,
  hubspotTimeoutMs: 30000,
};

// -----------------------------------------------------------------------------
// Derived, self-checking flags. A misconfiguration is caught HERE, at the top of
// the pipeline, instead of surfacing 40 nodes later as an unexplained 401.
// -----------------------------------------------------------------------------
const derived = {
  _cfgIsLive: CONFIG.runMode === 'live' && CONFIG.liveArmed === true,
  _cfgWritesCrm: CONFIG.runMode === 'live' && CONFIG.liveArmed === true
                 && CONFIG.hubspotEnabled === true && CONFIG.hubspotDryRun === false,
  _cfgAutoRejectArmed: CONFIG.autoRejectEnabled === true
                 && (CONFIG.runMode === 'live' || CONFIG.runMode === 'dry_run'),
  _cfgSelfCheck: [
    CONFIG.strongFit > CONFIG.goodFit ? null : 'strongFit must exceed goodFit',
    CONFIG.goodFit > CONFIG.needsReview ? null : 'goodFit must exceed needsReview',
    /_v3$/.test(CONFIG.auditTab) || CONFIG.environment === 'prod' ? null
      : 'auditTab is not a _v3 tab but environment is not prod — v2 data at risk',
    /_v3$/.test(CONFIG.d1Table) || CONFIG.environment === 'prod' ? null
      : 'd1Table is not the _v3 table but environment is not prod — v2 data at risk',
    CONFIG.runMode === 'live' && !CONFIG.liveArmed
      ? 'runMode=live but liveArmed=false — CRM writes stay suppressed (this is a safe state, not an error)'
      : null,
  ].filter(Boolean),
};

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  out.push({
    // Input json first, config on top: config is authoritative, no input key is
    // ever dropped, binary is passed through untouched.
    json: { ...(item.json || {}), ...CONFIG, ...derived },
    binary: item.binary,
    pairedItem: i,
  });
}
return out;

