={{ (() => {
  const payload = $json._chat.payload;
  const c = payload.cardsV2[0].card;
  const w = c.sections[0].widgets;
  const lines = [];

  lines.push('*' + c.header.title + '*');
  lines.push(c.header.subtitle);
  lines.push('');

  for (const widget of w) {
    const dt = widget.decoratedText;
    if (!dt) continue;
    const label = dt.topLabel || '';
    let text = (dt.text || '').split('<b>').join('*').split('</b>').join('*');
    lines.push('*' + label + ':* ' + text);
  }
  lines.push('');

  if (c.sections.length > 1 && c.sections[1] && c.sections[1].widgets) {
    const st = c.sections[1].widgets[0] && c.sections[1].widgets[0].textParagraph && c.sections[1].widgets[0].textParagraph.text;
    if (st) { lines.push('*Summary:*'); lines.push(st); lines.push(''); }
  }

  if (c.sections.length > 2 && c.sections[2] && c.sections[2].widgets) {
    const qt = c.sections[2].widgets[0] && c.sections[2].widgets[0].textParagraph && c.sections[2].widgets[0].textParagraph.text;
    if (qt) { lines.push('*Suggested Interview Questions:*'); lines.push(qt); lines.push(''); }
  }

  return JSON.stringify({ text: lines.join('\n') });
})() }}

